import AppKit

/// What Notch puts on the clipboard: the text of a dictation or of TEXT.
///
/// With INCOGNITO on, that text is kept out of sight as far as the clipboard allows:
/// - It is marked the way password managers mark a password: "concealed" (never show or keep it), "transient" and
///   "auto-generated" (only there for a moment). Clipboard managers and history apps that follow these common
///   markers (Maccy, Raycast, Alfred, Paste, Pastebot, LaunchBar and others; see nspasteboard.org) leave it out.
/// - The text itself is not even on the clipboard until an app pastes it: the clipboard only holds a promise, and
///   Notch hands the text over at the moment of the paste. An app that merely looks at what is there sees the
///   markers, not the words.
/// - It stays on this Mac: Universal Clipboard does not hand it to your iPhone or iPad.
/// - It does not stay: a dictation's text goes half a second after it was pasted, a TEXT grab's after 90 seconds,
///   and the clipboard gets back what it held before. Copy something yourself meanwhile, and that stays instead.
///
/// What no marker can stop: an app that ignores the markers and asks for the text while it is there.
enum Clipboard {
    private static let marks = ["org.nspasteboard.ConcealedType", "org.nspasteboard.TransientType",
                                "org.nspasteboard.AutoGeneratedType", "de.petermaurer.TransientPasteboardType"].map { NSPasteboard.PasteboardType($0) }
    private static var lender: Lender?   // the promise on the clipboard now; the clipboard itself does not keep it alive
    private static var mine: (count: Int, before: [NSPasteboardItem])?   // hidden text of ours on the clipboard, and what it replaced

    /// INCOGNITO in Settings.
    static var incognito: Bool { UserDefaults.standard.bool(forKey: Prefs.incognito) }

    /// Puts `text` on the clipboard: plainly, or, when `incognito`, marked, kept on this Mac and handed over only when
    /// an app pastes it; `taken` then runs (on the main thread) the first time one does.
    /// `before` is what `save` returned just before: what the clipboard is to get back.
    /// Returns the clipboard's change count, so a later `restore` can tell whether anything else used it since.
    @discardableResult static func put(_ text: String, incognito: Bool, before: [NSPasteboardItem] = [], on board: NSPasteboard = .general, taken: (() -> Void)? = nil) -> Int {
        let item = NSPasteboardItem()
        if incognito {
            marks.forEach { item.setData(Data(), forType: $0) }
            let promise = Lender(text, taken: taken)
            item.setDataProvider(promise, forTypes: [.string])
            lender = promise
            board.prepareForNewContents(with: .currentHostOnly)
        } else {
            item.setString(text, forType: .string)
            board.clearContents()
        }
        board.writeObjects([item])
        mine = incognito ? (board.changeCount, before) : nil
        return board.changeCount
    }

    /// What is on the clipboard now, copied out so it can be put back later. If that is hidden text of ours, what
    /// it replaced: hidden text is never kept for later, so it cannot come back once its time is up.
    static func save(_ board: NSPasteboard = .general) -> [NSPasteboardItem] {
        if let mine, mine.count == board.changeCount { return mine.before }
        return (board.pasteboardItems ?? []).map { old in
            let copy = NSPasteboardItem()
            for type in old.types { if let data = old.data(forType: type) { copy.setData(data, forType: type) } }
            return copy
        }
    }

    /// Puts `saved` back after `delay` seconds, unless something else used the clipboard after `count`
    /// (you copied something yourself meanwhile: that stays).
    static func restore(_ saved: [NSPasteboardItem], after delay: Double, unlessChangedSince count: Int, on board: NSPasteboard = .general) {
        DispatchQueue.main.asyncAfter(deadline: .now() + delay) {
            guard board.changeCount == count else { return }
            mine = nil
            board.clearContents()
            if !saved.isEmpty { board.writeObjects(saved) }
        }
    }
}

/// The promise behind hidden text: macOS asks it for the words when an app pastes, and only then.
private final class Lender: NSObject, NSPasteboardItemDataProvider {
    private let text: String
    private var taken: (() -> Void)?

    init(_ text: String, taken: (() -> Void)?) {
        self.text = text
        self.taken = taken
    }

    func pasteboard(_: NSPasteboard?, item: NSPasteboardItem, provideDataForType type: NSPasteboard.PasteboardType) {
        item.setString(text, forType: type)
        let first = taken
        taken = nil
        first?()
    }
}
